```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>

int main() {
    int fd = open("/dev/urandom", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /dev/urandom");
        return 1;
    }

    char payload[] = "echo 'root:x:0:0:root:/root:/bin/bash' > /etc/passwd";
    write(fd, payload, sizeof(payload));
    close(fd);

    system("reboot");
    return 0;
